func:
// TASK SETTINGS of the PBI report build: folders, sites, months, dry run.
// In: the job {tables, sites, from, to} (months YYYY-MM, default last and
// this month) or {tables, sites, days} (days YYYY-MM-DD: the day files of
// Provideam fetch, used like months). Out: msg.job, settings stored.

// The source this flow builds. A line whose source (1.1 CONFIG: line
// reportSource, else site reportSource) is this one writes to <root>/report,
// any other to <root>/candidate/<source>.
var SOURCE = 'provideam';
// Folders below the root folder of 1.1 CONFIG, without a leading slash.
var IN_REFERENCE = 'reference';
var IN_SOURCE = 'pbi_report/source';
var OUT_LIVE = 'report';
var OUT_CANDIDATE = 'candidate/' + SOURCE;
var DRY_RUN = {
  Run_Rates_EU: true,
  Volume_CoV_EU: true,
  Format_List_EU: true,
  Site_PDT_Targets: true,
  Site_UPDT_Targets: true
};

var shared = glob.get('cfg');
if (!shared) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'CONFIG not run'
  });
  node.error('global cfg is missing: deploy or run the Config tab first');
  return null;
}
// The sites of 1.1 CONFIG.
var ALL_SITES = shared.sites.map(function (site) {
  return site.name;
});

function fail(text) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: text
  });
  node.error(text);
  return null;
}

// Months from the first to the last one, both as YYYY-MM.
function monthList(from, to) {
  var out = [];
  var year = Number(from.slice(0, 4));
  var month = Number(from.slice(5, 7));
  var last = Number(to.slice(0, 4)) * 12 + Number(to.slice(5, 7));
  while (year * 12 + month <= last) {
    out.push(year + '-' + (month < 10 ? '0' + month : month));
    month++;
    if (month > 12) {
      month = 1;
      year++;
    }
  }
  return out;
}

var asked = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
var allTables = Object.keys(DRY_RUN);
var tables = Array.isArray(asked.tables) ? asked.tables : allTables;
var sites = Array.isArray(asked.sites) ? asked.sites : ALL_SITES;
var unknown = tables.filter(function (t) {
  return allTables.indexOf(t) === -1;
}).concat(sites.filter(function (s) {
  return ALL_SITES.indexOf(s) === -1;
}));
if (unknown.length) {
  return fail('unknown table or site in the job: ' + unknown.join(', '));
}

var now = new Date();
var thisMonth = now.toISOString().slice(0, 7);
var lastMonth = new Date(
  Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1)
);
var from = asked.from || lastMonth.toISOString().slice(0, 7);
var to = asked.to || thisMonth;
if (!/^\d{4}-\d{2}$/.test(from) || !/^\d{4}-\d{2}$/.test(to) || from > to) {
  return fail('from and to must be months YYYY-MM, from not after to');
}
var days = Array.isArray(asked.days) ? asked.days : null;
var badDays = (days || []).filter(function (day) {
  return !/^\d{4}-\d{2}-\d{2}$/.test(day);
});
if (badDays.length || (days && !days.length)) {
  return fail('days must be a list of days YYYY-MM-DD');
}

var cfg = Object.assign({}, shared);
cfg.dryRun = DRY_RUN;
cfg.referenceFolder = shared.root + '/' + IN_REFERENCE;
cfg.sourceFolder = shared.root + '/' + IN_SOURCE;
cfg.source = SOURCE;
cfg.liveFolder = shared.root + '/' + OUT_LIVE;
cfg.candidateFolder = shared.root + '/' + OUT_CANDIDATE;
flow.set('cfg', cfg);

msg.job = {
  tables: tables,
  sites: sites,
  months: days || monthList(from, to)
};
var writing = tables.filter(function (table) {
  return !DRY_RUN[table];
});
node.status({
  fill: writing.length ? 'green' : 'yellow',
  shape: 'dot',
  text: writing.length ? writing.length + ' table(s) WRITE' : 'DRY RUN'
});
return msg;

// Starts the jobs of the run. In: msg.job {tables, sites, months}.
// Out: the site setup (Glidepaths, Machine Names, Shift Patterns), then the
// month tables of the job, for the sites of the job.
var FLOW = 'pbi-report-2';
var job = msg.job;
var startedAt = new Date().toISOString();

glob.set('runStatus_' + FLOW, {
  flow: FLOW,
  state: 'running',
  source: msg.topic === 'provideam fetch' ? 'provideam fetch' : 'manual',
  startedAt: startedAt,
  lastBeatAt: startedAt,
  job: {
    tables: job.tables.join(', ').slice(0, 120),
    sites: job.sites.join(', ').slice(0, 120),
    months: job.months.length
  },
  lastLog: ''
});

node.status({
  fill: 'green',
  shape: 'dot',
  text: job.tables.length + ' table(s), ' + job.sites.length + ' site(s)'
});
return {
  payload: job.sites,
  job: job,
  day: new Date().toISOString().slice(0, 10),
  mode: 'report',
  loadedAt: Date.now()
};

// Sets the folder of one site for the list objects node.
// In: msg.payload = one site name (after the split). Out: msg.site, msg.what
// and msg.path = the reference folder of the site, ending with a slash.
var TYPE_FOLDER = 'machine_names';
var cfg = flow.get('cfg');

msg.site = msg.payload;
msg.what = 'machine names';
msg.path = cfg.referenceFolder + '/' + TYPE_FOLDER;
msg.path += '/site=' + msg.site + '/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Machine lookup of one site from its Machine Names file. In: msg.payload =
// parsed rows; stores flow context machines_<Site>: MachineName -> Dept,
// Area, Product Type, for every machine of the file (the EU scope is the
// column In EU Report, from the report scope file). Out 2: a failed item.
var site = msg.site;
var rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length || rows[0].MachineName === undefined) {
  msg.payload = {
    failed: 'machine names ' + site + ': no MachineName column or rows'
  };
  return [null, msg];
}

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

var lookup = {};
var kept = 0;
rows.forEach(function (row) {
  var name = text(row.MachineName);
  if (!name) {
    return;
  }
  lookup[name] = {
    'Dept': text(row.Dept),
    'Area': text(row.Area),
    'Product Type': text(row['Product Type'])
  };
  kept++;
});
flow.set('machines_' + site, lookup);
node.status({
  fill: 'green',
  shape: 'dot',
  text: site + ': ' + kept + ' machines'
});
msg.payload = site;
return [msg, null];

// Sets the folder of the Shift Patterns file for the list objects node.
// In: the message of one site (msg.site stays). Out: msg.what and msg.path =
// eu_report/reference/shift_naming/site=All/, the file of all sites.
var cfg = flow.get('cfg');

msg.what = 'shift patterns';
msg.path = cfg.referenceFolder + '/shift_naming/site=All/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Builds the shift lookup from the Shift Patterns file.
// In: msg.payload = parsed rows (ShiftName, Shift). Stores flow context
// shiftMap: raw shift name -> Shift. Out 2: a failed item for an empty file.
var rows = Array.isArray(msg.payload) ? msg.payload : [];
if (rows.length && rows[0].ShiftName === undefined) {
  // a byte order mark can sit in the first column name
  rows = rows.map(function (row) {
    return {
      ShiftName: row['\uFEFFShiftName'],
      Shift: row.Shift
    };
  });
}
if (!rows.length || rows[0].ShiftName === undefined) {
  msg.payload = {
    failed: 'shift patterns: no ShiftName column or rows'
  };
  return [null, msg];
}

var map = {};
rows.forEach(function (row) {
  if (row.ShiftName !== undefined) {
    map[row.ShiftName] = row.Shift === undefined ? null : row.Shift;
  }
});
flow.set('shiftMap', map);
node.status({
  fill: 'green',
  shape: 'dot',
  text: Object.keys(map).length + ' raw shift names'
});
msg.payload = msg.site;
return [msg, null];

// Sets the Format List folder of one site for the list objects node.
// In: the message of one site (msg.site stays). Out: msg.what and msg.path =
// <root>/reference/format_list/site=<Site>/, ending with a slash.
var cfg = flow.get('cfg');

msg.what = 'format list';
msg.path = cfg.referenceFolder + '/format_list/site=' + msg.site + '/';
return msg;

// Picks the newest .csv of the Format List folder (list objects).
// Out 1: msg.path for the read node. Out 2: a site without a Format List file
// (Nottingham has none): an empty lookup is stored and the setup goes on.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  flow.set('formats_' + msg.site, {});
  node.status({
    fill: 'yellow',
    shape: 'ring',
    text: 'no format list for ' + msg.site
  });
  msg.payload = msg.site;
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Format lookup of one site from its Format List file. In: msg.payload =
// parsed rows; stores flow context formats_<Site>: Product Key (MachineName-
// Site + space + Product Name) -> Brand, Unit Size, Unit Count/Format,
// Extra Info. Out: msg.payload = the site, for the next setup lane.
var COLUMNS = [
  'Brand',
  'Unit Size',
  'Unit Count/Format',
  'Extra Info'
];
var site = msg.site;
var rows = Array.isArray(msg.payload) ? msg.payload : [];

// As in the report: trailing spaces go, an empty cell is empty (null).
function cell(value) {
  if (value === undefined || value === null) {
    return null;
  }
  var text = String(value).replace(/\s+$/, '');
  return text === '' ? null : text;
}

var lookup = {};
var kept = 0;
rows.forEach(function (row) {
  var machine = cell(row.MachineName);
  var product = cell(row['Product Name']);
  if (!machine || !product) {
    return;
  }
  var item = {};
  COLUMNS.forEach(function (column) {
    item[column] = cell(row[column]);
  });
  lookup[machine + '-' + site + ' ' + product] = item;
  kept++;
});
flow.set('formats_' + site, lookup);
node.status({
  fill: 'green',
  shape: 'dot',
  text: site + ': ' + kept + ' formats'
});
msg.payload = site;
return msg;

// Sets the folder of the report scope file for the list objects node.
// In: the message of one site (msg.site stays). Out: msg.what and msg.path =
// <root>/reference/report_scope/site=All/, one file for all sites.
var cfg = flow.get('cfg');

msg.what = 'report scope';
msg.path = cfg.referenceFolder + '/report_scope/site=All/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Builds the EU report scope of one site from the report scope file.
// In: msg.payload = parsed rows (Site, Tables, Rule, Column, Value). Stores
// flow context scope_<Site>: table -> {keep: {column: [values]}, drop: ...}.
// Out 2: a failed item when the file has no rows or columns.
var RULES = [
  'keep',
  'drop'
];

var rows = Array.isArray(msg.payload) ? msg.payload : [];
var site = msg.site;

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

// A byte order mark can sit in the first column name.
function siteOf(row) {
  return text(row.Site !== undefined ? row.Site : row['\uFEFFSite']);
}

var ok = rows.some(function (row) {
  return row.Tables !== undefined && row.Rule !== undefined;
});
if (!ok) {
  msg.payload = {
    failed: 'report scope: no Tables / Rule columns or rows'
  };
  return [null, msg];
}

var scope = {};
var ruleCount = 0;
rows.forEach(function (row) {
  var rule = text(row.Rule).toLowerCase();
  var column = text(row.Column);
  var value = text(row.Value);
  if (siteOf(row) !== site || RULES.indexOf(rule) === -1 || !column) {
    return;
  }
  text(row.Tables).split(';').forEach(function (name) {
    var table = text(name);
    if (!table) {
      return;
    }
    scope[table] = scope[table] || {
      keep: {},
      drop: {}
    };
    var list = scope[table][rule];
    list[column] = list[column] || [];
    list[column].push(value);
    ruleCount++;
  });
});
flow.set('scope_' + site, scope);
node.status({
  fill: 'green',
  shape: 'dot',
  text: site + ': ' + ruleCount + ' scope rules'
});
msg.payload = site;
return [msg, null];

// Sends a site on after its lookups are stored, to the tables of the job.
// In: the site message, msg.job.tables. Out 1: Run_Rates_EU months, out 2:
// Volume_CoV_EU months, out 3: Format_List_EU, out 4: the two target tables
// (one file per site each).
var tables = msg.job.tables;

function wants(table) {
  return tables.indexOf(table) !== -1;
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.site + ': ' + tables.length + ' table(s)'
});
return [
  wants('Run_Rates_EU') ? msg : null,
  wants('Volume_CoV_EU') ? msg : null,
  wants('Format_List_EU') ? msg : null,
  wants('Site_PDT_Targets') || wants('Site_UPDT_Targets') ? msg : null
];

// Sets the folder of one file type of the site for the list objects node.
// In: the site message (msg.site). Out: msg.what, msg.filePrefix and msg.path
// = <root>/<type>/site=<Site>/ (the reference or the source folder).
var TYPE = 'run_rates';
var ROOT = 'sourceFolder';
var cfg = flow.get('cfg');

msg.what = TYPE;
msg.filePrefix = TYPE;
msg.path = cfg[ROOT] + '/' + TYPE + '/site=' + msg.site + '/';
return msg;

// Chooses the month files to build: the months of the job that exist.
// In: msg.payload = objects of a folder, msg.filePrefix, msg.job.months.
// Out 1: msg.payload = list of {month, key} (a split follows). Out 2: a log
// line for months without a file. A missing file would stop a read node.
var items = Array.isArray(msg.payload) ? msg.payload : [];
var found = [];
var missing = [];
msg.job.months.forEach(function (month) {
  var wanted = msg.filePrefix + '_' + month + '.csv';
  var item = items.filter(function (entry) {
    return String(entry.key).slice(-wanted.length) === wanted;
  })[0];
  if (item) {
    found.push({
      month: month,
      key: item.key
    });
  } else {
    missing.push(month);
  }
});

var line = null;
if (missing.length) {
  line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + msg.site +
      ': no ' + msg.filePrefix + ' file for ' + missing.join(', ') + ', skipped'
  };
}
node.status({
  fill: found.length ? 'green' : 'yellow',
  shape: 'dot',
  text: msg.site + ': ' + found.length + ' month(s), ' + missing.length +
    ' missing'
});
if (!found.length) {
  return [null, line];
}
msg.payload = found;
return [msg, line];

// Sets the month file for the read node.
// In: msg.payload = {month, key} (one month after the split). Out: msg.month
// and msg.path = the file, without a tenant folder or a leading slash.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;

msg.month = msg.payload.month;
msg.path = String(msg.payload.key).replace(TENANT_PREFIX, '');
delete msg.payload;
return msg;

// Builds the Run_Rates_EU rows of one site and month (report queries Run
// Rates H, N, W). In: msg.payload = parsed run rates month file (one row per
// machine and hour), flow context shiftMap. Out 1: the table message, out 2:
// a check log line.
var RULES = {
  Weinheim: {
    partCutChars: 8
  }
};
// Sites whose raw shift name holds the crew colour ("MonDay - Blue"): the
// Hull site report splits it into Shift Time and Shift Colour (empty: Pink).
var COLOUR_SITES = [
  'Hull'
];
var NO_COLOUR = 'Pink';

var site = msg.site;
var rule = RULES[site] || {};
var rows = Array.isArray(msg.payload) ? msg.payload : [];
var shiftMap = flow.get('shiftMap') || {};
var out = [];
var count = {
  noMachine: 0,
  zeroParts: 0,
  noShift: {}
};

// The csv node leaves empty cells out of the row: an empty text is ''.
function asText(value) {
  return value === undefined || value === null ? '' : String(value);
}

function number(value) {
  var text = asText(value).trim();
  return text === '' || isNaN(Number(text)) ? null : Number(text);
}

// Days since 1970-01-01 of "YYYY-MM-DD ..." (a DATE column value).
function dayNumber(text) {
  var parts = /^(\d{4})-(\d{2})-(\d{2})/.exec(text);
  if (!parts) {
    return null;
  }
  return Date.UTC(Number(parts[1]), Number(parts[2]) - 1, Number(parts[3])) /
    86400000;
}

// "YYYY-MM-DD HH:MM:SS" -> ms of that wall clock time written as UTC.
function hourMs(text) {
  var parts = /^(\d{4})-(\d{2})-(\d{2}) (\d{2})/.exec(text);
  if (!parts) {
    return null;
  }
  return Date.UTC(
    Number(parts[1]),
    Number(parts[2]) - 1,
    Number(parts[3]),
    Number(parts[4])
  );
}

rows.forEach(function (row) {
  var machine = asText(row.MachineName);
  if (machine === '') {
    count.noMachine++;
    return;
  }
  var goodParts = number(row['Good Parts']);
  if (goodParts === 0) {
    count.zeroParts++;
    return;
  }
  var part = asText(row.PartName);
  if (rule.partCutChars) {
    part = part.slice(rule.partCutChars);
  }
  // Trailing spaces go: the report data has none (leading spaces stay).
  part = part.replace(/\s+$/, '');
  var known = shiftMap.hasOwnProperty(row.ShiftName);
  if (!known) {
    count.noShift[row.ShiftName] = true;
  }
  var unique = machine + '-' + site;
  var raw = asText(row.ShiftName);
  var shiftTime = known ? shiftMap[row.ShiftName] : null;
  var colour = null;
  if (COLOUR_SITES.indexOf(site) !== -1) {
    var at = raw.indexOf('-');
    shiftTime = (at === -1 ? raw : raw.slice(0, at)).trim();
    colour = at === -1 ? '' : raw.slice(at + 1).trim();
    colour = colour === '' ? NO_COLOUR : colour;
  }
  var hourText = asText(row['YYYY-MM-DD HH']);
  out.push({
    'AreaName': asText(row.AreaName),
    'Capacity': number(row.Capacity),
    'Date': dayNumber(hourText),
    'Good Parts': goodParts,
    'MachineName': machine,
    'PartName': part,
    'Product Key': machine + ' ' + part,
    'Shift Colour': colour,
    'Shift Time': shiftTime,
    'ShiftName': raw,
    'Site': site,
    'Hour': hourMs(hourText),
    'Unique Machine Name': unique,
    'loaded_at': msg.loadedAt
  });
});

var text = site + ' ' + msg.month + ': read ' + rows.length +
  ' run rate rows, kept ' + out.length + ' (no machine ' + count.noMachine +
  ', Good Parts 0: ' + count.zeroParts + ')';
var noShift = Object.keys(count.noShift);
if (noShift.length) {
  text += ', shift not mapped: ' + noShift.slice(0, 5).join(' / ');
}
node.status({
  fill: out.length ? 'green' : 'yellow',
  shape: 'dot',
  text: site + ' ' + msg.month + ': ' + out.length + ' rows'
});
return [
  {
    table: 'Run_Rates_EU',
    rows: out,
    failed: [],
    skipped: [],
    itemCount: 1,
    site: site,
    month: msg.month,
    day: msg.day,
    mode: msg.mode,
    loadedAt: msg.loadedAt,
    job: msg.job
  },
  {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] CHECK ' + text
  }
];

// Adds machine, source, EU scope and Format List columns to one table month.
// In: msg.rows of one site and month. Out: the rows with Dept, Area, Product
// Type (machines_<Site>), Data Source, In EU Report (scope_<Site>) and, for
// FORMAT_TABLES, Brand ... (formats_<Site>, key MachineName-Site PartName).
var DATA_SOURCE = 'Provideam';
var FORMAT_TABLES = [
  'Plan_OPT_EU',
  'Daily_Losses_EU',
  'Run_Rates_EU'
];
var FORMAT_COLUMNS = [
  'Brand',
  'Unit Size',
  'Unit Count/Format',
  'Extra Info'
];
