var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = TABLE + ' ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';
if (msg.out) {
  sizes += ' to ' + msg.out;
}

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun[TABLE]) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file path of a table with one file per site (no month):
// <report>/<table>/site=<Site>/<table>.parquet. In: the parquet node output
// (msg.table, msg.site). Out: msg.path. A rerun replaces the site's file.
var cfg = flow.get('cfg');

msg.path = cfg.liveFolder + '/' + msg.table + '/site=' + msg.site;
msg.path += '/' + msg.table + '.parquet';
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the folder of one file type of the site for the list objects node.
// In: the site message (msg.site). Out: msg.what, msg.filePrefix and msg.path
// = <root>/<type>/site=<Site>/ (the reference or the source folder).
var TYPE = 'glidepaths';
var ROOT = 'referenceFolder';
var cfg = flow.get('cfg');

msg.what = TYPE;
msg.filePrefix = TYPE;
msg.path = cfg[ROOT] + '/' + TYPE + '/site=' + msg.site + '/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Builds Site_PDT_Targets and Site_UPDT_Targets of one site from its
// Glidepaths file: one row per line and month column. In: msg.payload =
// parsed rows. Out 1: PDT table, out 2: UPDT table, out 3: a check log line.
var TABLES = [
  {
    table: 'Site_PDT_Targets',
    bucket: 'Planned Downtime (Total)',
    column: 'PDT Target'
  },
  {
    table: 'Site_UPDT_Targets',
    bucket: 'Unplanned Downtime (Total)',
    column: 'UPDT Target'
  }
];
var site = msg.site;
var rows = Array.isArray(msg.payload) ? msg.payload : [];

// The file starts with a byte order mark: it sits in the first column name.
function clean(row) {
  var out = {};
  Object.keys(row).forEach(function (column) {
    out[column.replace(/﻿/g, '')] = row[column];
  });
  return out;
}

// Days since 1970-01-01 of a month column 01/MM/YYYY (a DATE column value).
function dayNumber(text) {
  var parts = text.split('/');
  return Date.UTC(Number(parts[2]), Number(parts[1]) - 1, Number(parts[0])) /
    86400000;
}

// 25.9 (percent in the file) -> 0.259; an empty cell is empty.
function fraction(value) {
  var text = value === undefined || value === null ? '' : String(value).trim();
  if (text === '' || isNaN(Number(text))) {
    return null;
  }
  return Math.round(Number(text) * 100) / 10000;
}

function tableRows(spec) {
  var out = [];
  rows.map(clean).forEach(function (row) {
    if (row['OEE Bucket'] !== spec.bucket || !row.Line) {
      return;
    }
    Object.keys(row).forEach(function (column) {
      if (!/^\d{2}\/\d{2}\/\d{4}$/.test(column)) {
        return;
      }
      var item = {
        'Site': site,
        'Line': row.Line,
        'OEE Bucket': spec.bucket,
        'Date': dayNumber(column)
      };
      item[spec.column] = fraction(row[column]);
      item['Volume Key'] = row.Line + ' ' + column;
      item['loaded_at'] = msg.loadedAt;
      out.push(item);
    });
  });
  return out;
}

var messages = TABLES.map(function (spec) {
  if (msg.job.tables.indexOf(spec.table) === -1) {
    return null;
  }
  return {
    table: spec.table,
    rows: tableRows(spec),
    failed: [],
    skipped: [],
    itemCount: 1,
    site: site,
    day: msg.day,
    mode: msg.mode,
    loadedAt: msg.loadedAt,
    job: msg.job
  };
});
var text = site + ': read ' + rows.length + ' glidepath rows';
messages.forEach(function (item) {
  if (item) {
    text += ', ' + item.table + ' ' + item.rows.length + ' rows';
  }
});
node.status({
  fill: 'green',
  shape: 'dot',
  text: text.slice(0, 60)
});
return [
  messages[0],
  messages[1],
  {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] CHECK ' + text
  }
];

// Decides what happens with the table Site_PDT_Targets.
// In: msg.rows, msg.failed, msg.skipped. Out 1: msg.payload = rows for the
// parquet node. Out 2: a log line. A failed item means nothing is written.
var TABLE = 'Site_PDT_Targets';
var cfg = flow.get('cfg');
var rows = msg.rows;
var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = TABLE + ' ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';
if (msg.out) {
  sizes += ' to ' + msg.out;
}

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun[TABLE]) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file path of a table with one file per site (no month):
// <report>/<table>/site=<Site>/<table>.parquet. In: the parquet node output
// (msg.table, msg.site). Out: msg.path. A rerun replaces the site's file.
var cfg = flow.get('cfg');

msg.path = cfg.liveFolder + '/' + msg.table + '/site=' + msg.site;
msg.path += '/' + msg.table + '.parquet';
msg.filename = msg.path.split('/').pop();
return msg;

// Decides what happens with the table Site_UPDT_Targets.
// In: msg.rows, msg.failed, msg.skipped. Out 1: msg.payload = rows for the
// parquet node. Out 2: a log line. A failed item means nothing is written.
var TABLE = 'Site_UPDT_Targets';
var cfg = flow.get('cfg');
var rows = msg.rows;
var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = TABLE + ' ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';
if (msg.out) {
  sizes += ' to ' + msg.out;
}

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun[TABLE]) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file path of a table with one file per site (no month):
// <report>/<table>/site=<Site>/<table>.parquet. In: the parquet node output
// (msg.table, msg.site). Out: msg.path. A rerun replaces the site's file.
var cfg = flow.get('cfg');

msg.path = cfg.liveFolder + '/' + msg.table + '/site=' + msg.site;
msg.path += '/' + msg.table + '.parquet';
msg.filename = msg.path.split('/').pop();
return msg;

// Turns a failed item into a log line. In: msg.payload = {failed: text}
// (a file that was not found or empty). Out: the log line. Nothing is built
// for the site, so no table file is written for it in this run.
var line = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] FAILED, NOTHING WRITTEN: ' +
    msg.payload.failed
};
return line;

// Turns an error caught by the catch node into a log line.
// In: the message of a catch node (msg.error).
// Out: a log line for the shared log. Errors of the log nodes themselves
// are dropped (no log loop).
var err = msg.error || {};
var source = (err.source && err.source.name) || 'unknown node';

function textOf(value) {
  if (value === undefined || value === null) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  return JSON.stringify(value);
}

// Takes the API message out of an error body when there is one.
function apiMessage(value) {
  var body = value;
  if (typeof value === 'string') {
    try {
      body = JSON.parse(value);
    } catch (e) {
      return value;
    }
  }
  var data = body && body.data;
  var list = (data && data.errors) || (body && body.errors);
  if (list && list.length && list[0].message) {
    return list[0].message;
  }
  return textOf(value);
}

if (msg.logBatch) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'log write failed'
  });
  return null;
}

var text = '';
if (msg.day) {
  text += msg.day + ' [' + msg.mode + '] ';
}
text += 'ERROR in ' + source + ': ' + apiMessage(err.message);
return {
  topic: 'log',
  payload: text,
  level: 'error',
  source: source
};

// Turns one log message into a row for the log file.
// In: msg.payload = log text (optional msg.level and msg.source).
// Out: msg.payload = the row, msg.line = the text for the debug node.
var FLOW_NAME = 'pbi-report-2';
var cfg = flow.get('cfg') || {};
var text = String(msg.payload);

var seq = (flow.get('logSeq') || 0) + 1;
flow.set('logSeq', seq);

// Most lines start with the production day and the mode: "2026-09-01 [x] ".
var day = '';
var mode = '';
var message = text;
var parts = /^(\d{4}-\d{2}-\d{2}) \[([^\]]*)\] ([\s\S]*)$/.exec(text);
if (parts) {
  day = parts[1];
  mode = parts[2];
  message = parts[3];
}

var level = msg.level;
if (!level) {
  if (/FAILED/.test(message)) {
    level = 'failed';
  } else if (/NOTHING TO WRITE/.test(message)) {
    level = 'warn';
  } else {
    level = 'info';
  }
}

msg.line = text;
msg.payload = {
  ts_utc: new Date().toISOString(),
  seq: seq,
  flow: FLOW_NAME,
  site: cfg.site || 'all',
  production_day: day,
  mode: mode,
  level: level,
  source: msg.source || 'flow',
  message: message
};
return msg;

// Notes the time of the newest log line of the tab in global context
// lastLog_<flow>. In: every log line (a tap behind the log formatter). Out:
// nothing. A new line clears done_<flow>, so the next quiet period is shown.
var FLOW = 'pbi-report-2';
glob.set('lastLog_' + FLOW, Date.now());
glob.set('done_' + FLOW, false);
var status = glob.get('runStatus_' + FLOW);
if (status) {
  var row = msg.payload || {};
  var line = String(row.message || msg.line || '');
  status.lastBeatAt = new Date().toISOString();
  status.lastLog = line.slice(0, 160);
  if (row.level === 'failed' || row.level === 'error') {
    status.state = 'failed';
  }
  glob.set('runStatus_' + FLOW, status);
}
return null;

// Prepares the write of one batch of log rows (the read node runs next).
// In: msg.payload = array of log rows from the join node.
// Out: msg.path = file of the month, msg.logRows, msg.logBatchId, no payload.
// msg.logBatch keeps errors of the log nodes themselves out of the log.
var FLOW_NAME = 'pbi-report-2';
var cfg = flow.get('cfg') || {};
var root = cfg.root || 'logs_without_root';
var rows = msg.payload;
var month = rows[0].ts_utc.slice(0, 7);

var batchNo = (flow.get('logBatchNo') || 0) + 1;
flow.set('logBatchNo', batchNo);

msg.logRows = rows;
msg.path = root + '/logs/' + FLOW_NAME + '/log_' + month + '.csv';
msg.logBatch = true;
msg.logBatchId = rows[0].ts_utc + '#' + batchNo;
delete msg.payload;
return msg;

// Adds the rows of one batch to the log file of the month.
// In: msg.payload = the old file (read answered) or nothing (no answer).
// Out: msg.payload = the whole new file, the data lake has no append.
// The same batch can arrive twice (read answer, then the wait): once only.
var SEPARATOR = ',';
var KEEP_IDS = 50;
var COLUMNS = [
  'ts_utc',
  'seq',
  'flow',
  'site',
  'production_day',
  'mode',
  'level',
  'source',
  'message'
];

// Quotes inside a field are doubled, line breaks become a space.
function quote(value) {
  var text = (value === undefined || value === null) ? '' : String(value);
  text = text.replace(/"/g, '""').replace(/[\r\n]+/g, ' ');
  return '"' + text + '"';
}

function lineOf(row) {
  return COLUMNS.map(function (name) {
    return quote(row[name]);
  }).join(SEPARATOR);
}

// The read node gives text, or a serialised buffer.
function decode(payload) {
  if (typeof payload === 'string') {
    return payload;
  }
  if (payload && payload.type === 'Buffer' && payload.data) {
    var bin = '';
    payload.data.forEach(function (byte) {
      bin += String.fromCharCode(byte);
    });
    try {
      return decodeURIComponent(escape(bin));
    } catch (e) {
      return bin;
    }
  }
  return null;
}

var rows = msg.logRows.slice();
rows.sort(function (a, b) {
  if (a.ts_utc !== b.ts_utc) {
    return a.ts_utc < b.ts_utc ? -1 : 1;
  }
  return a.seq - b.seq;
});

var done = flow.get('logDone') || [];
var known = flow.get('logKnown') || [];
if (done.indexOf(msg.logBatchId) >= 0) {
  return null;
}

var path = msg.path;
var old = '';
var problem = '';
if (msg.payload === undefined || msg.payload === null) {
  if (known.indexOf(path) >= 0) {
    problem = 'read gave no answer for a file written before';
  }
} else {
  old = decode(msg.payload);
  if (old === null) {
    old = '';
    problem = 'old file is not text';
  }
}
if (problem) {
  // Never replace the old file: write a new one with a time stamp.
  var stamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
  path = path.replace(/\.csv$/, '_' + stamp + '.csv');
  rows.push({
    ts_utc: new Date().toISOString(),
    seq: 0,
    flow: rows[0].flow,
    site: rows[0].site,
    production_day: '',
    mode: '',
    level: 'error',
    source: 'log',
    message: problem + ', wrote ' + path
  });
} else if (known.indexOf(path) < 0) {
  known.push(path);
  flow.set('logKnown', known);
}

var lines = [];
if (!old) {
  lines.push(COLUMNS.map(quote).join(SEPARATOR));
} else if (old.slice(-1) !== '\n') {
  old += '\n';
}
rows.forEach(function (row) {
  lines.push(lineOf(row));
});

done.push(msg.logBatchId);
flow.set('logDone', done.slice(-KEEP_IDS));

msg.payload = old + lines.join('\n') + '\n';
msg.path = path;
delete msg.logRows;
return msg;
